// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1 ether, 100 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        (bool okDep, ) = address(c).call{value: amount}("");
        assertTrue(okDep, "deposit should succeed");

        vm.prank(actor);
        bool ok;
        try c.withdraw() { ok = true; } catch { ok = false; }

        // Universal rule: after withdraw, the caller's recorded balance is
        // drained to zero (funds paid out) and the call did not revert.
        assertTrue(ok && c.balances(actor) == 0 && address(c).balance == 0,
            "withdraw must pay out and zero the caller's balance");
    }
}
